      body: JSON.stringify(body),
    });
    const project = await (await mutate('/api/projects', 'POST', { name: 'First' })).json();
    const other = await (await mutate('/api/projects', 'POST', { name: 'Other' })).json();
    const projectPath = `/api/projects/${project.id}`;
